# Good! Let me find more small cases to see if there's a pattern
from itertools import permutations
import time

def get_edges_small(n_cliques):
    edges = []
    for g in range(n_cliques):
        base = 3*g
        edges.append((base, base+1))
        edges.append((base, base+2))
        edges.append((base+1, base+2))
    for g in range(n_cliques-1):
        for i in range(3):
            edges.append((3*g+i, 3*g+3+i))
    return edges

def find_graceful_small(n_cliques, max_time=10):
    edges = get_edges_small(n_cliques)
    n_v = 3 * n_cliques
    n_e = len(edges)
    start = time.time()

    for perm in permutations(range(n_e+1), n_v):
        if time.time() - start > max_time:
            return None
        diffs = set()
        valid = True
        for u, v in edges:
            d = abs(perm[u] - perm[v])
            if d == 0 or d > n_e or d in diffs:
                valid = False
                break
            diffs.add(d)
        if valid:
            return list(perm)
    return None

for nc in range(1, 5):
    edges = get_edges_small(nc)
    n_e = len(edges)
    result = find_graceful_small(nc, max_time=15)
    print(f"n_cliques={nc}, n_edges={n_e}: {result}")
